import{_ as e,b as t,c as r,a3 as o}from"./chunks/framework.COIqWEEU.js";const i="/assets/image-20260620150830344.xmmIqzdM.png",s="/assets/image-20260620151737182.CyIS2jN2.png",l="/assets/image-20260620152830002.jHVFtrrk.png",b=JSON.parse('{"title":"轩执事交易系统","description":"易从来不是聪明者的游戏，更不需要勇者证明自己的勇气。","frontmatter":{"createTime":"2026年6月20日14:55:49","description":"易从来不是聪明者的游戏，更不需要勇者证明自己的勇气。"},"headers":[],"relativePath":"pages/交易/轩执事0007波段交易系统/1-总览.md","filePath":"pages/交易/轩执事0007波段交易系统/1-总览.md","lastUpdated":1795057516000}'),h={name:"pages/交易/轩执事0007波段交易系统/1-总览.md"};function p(n,a,d,c,m,u){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="轩执事交易系统" tabindex="-1">轩执事交易系统 <a class="header-anchor" href="#轩执事交易系统" aria-label="Permalink to &quot;轩执事交易系统&quot;">​</a></h1><h2 id="序言" tabindex="-1">序言： <a class="header-anchor" href="#序言" aria-label="Permalink to &quot;序言：&quot;">​</a></h2><blockquote><p>交易从来不是聪明者的游戏，更不需要勇者证明自己的勇气。</p></blockquote><p>交易系统目的是规范交易流程，总结能够复刻的订单，在下次出现相同情况能够处理并且盈利。</p><p>一笔订单大致分为以下步骤：背景分析、入场分析、止盈止损、订单管理、心态管理。</p><h2 id="背景分析" tabindex="-1">背景分析： <a class="header-anchor" href="#背景分析" aria-label="Permalink to &quot;背景分析：&quot;">​</a></h2><p>在下单之前，先建立这次交易的市场上下文，判断当前环境适不适合交易、机会来自哪里、风险可能从哪里来，以及什么条件下这笔交易成立或失效，这就是背景分析。</p><p>背景分析站一笔交易的80%，只有背景好了，交易胜率的概率才大。</p><p>主要是分析是否顺势，市场的支撑阻力在哪里，我们做的是波段，前方是否有一笔极速发起。</p><h2 id="入场分析" tabindex="-1">入场分析： <a class="header-anchor" href="#入场分析" aria-label="Permalink to &quot;入场分析：&quot;">​</a></h2><p>在背景分析已经确定“值得关注这个方向/品种”之后，把观点转化为可执行的交易动作——回答“现在是不是入场时机、在什么位置进、凭什么进、错了怎么退、赔率够不够</p><p>主要是通过交易库去分析行情的小逆势是否颓势</p><h2 id="止盈止损" tabindex="-1">止盈止损： <a class="header-anchor" href="#止盈止损" aria-label="Permalink to &quot;止盈止损：&quot;">​</a></h2><p>斐波拉契1.5到2的位置，或者等比</p><h2 id="订单管理" tabindex="-1">订单管理： <a class="header-anchor" href="#订单管理" aria-label="Permalink to &quot;订单管理：&quot;">​</a></h2><p>刚入场，有亏损，有盈利</p><h2 id="心态管理" tabindex="-1">心态管理： <a class="header-anchor" href="#心态管理" aria-label="Permalink to &quot;心态管理：&quot;">​</a></h2><h2 id="交易库" tabindex="-1">交易库： <a class="header-anchor" href="#交易库" aria-label="Permalink to &quot;交易库：&quot;">​</a></h2><h3 id="波段高低点的关系" tabindex="-1">波段高低点的关系： <a class="header-anchor" href="#波段高低点的关系" aria-label="Permalink to &quot;波段高低点的关系：&quot;">​</a></h3><p>行情是有惯性的，总是朝着阻力最小的方向前进，一波强势上涨回调后大概率会继续上涨，我一般把这个叫做波段高低点的关系。</p><p>类推逻辑，创出更高的高点，大概率不会创出更低的低点。</p><p><img src="'+i+'" alt="image-20260620150830344"></p><h3 id="波段混乱" tabindex="-1">波段混乱： <a class="header-anchor" href="#波段混乱" aria-label="Permalink to &quot;波段混乱：&quot;">​</a></h3><p>在波段高低点的关系中讲过，创出更高的高点大概率不会创出更低的低点，但是经过复盘，还有一种情况胜率非常高，在前高回调后再次突破高点，但是是假突破随后下跌创出上一次回调更低的低点，此时收回上一次的低点再入场做多胜率非常高。</p><p><img src="'+s+'" alt="image-20260620151737182"></p><h3 id="三推回测起点" tabindex="-1">三推回测起点： <a class="header-anchor" href="#三推回测起点" aria-label="Permalink to &quot;三推回测起点：&quot;">​</a></h3><p>三推回测起点是共识，所以可以把回测起点当做回调，这套系统的三推不是真正意义上的三推，只要出现三次上涨就算三推。</p><p><img src="'+l+'" alt="image-20260620152830002"></p><h2 id="本质" tabindex="-1">本质： <a class="header-anchor" href="#本质" aria-label="Permalink to &quot;本质：&quot;">​</a></h2><p>本质就是支阻互换的关系，利用市场的惯性盈利，往市场阻力最小的方向进行做单。</p><p>入场前先分析市场背景，如果 前面已经有个入场条件但是止损了，接下来就要谨慎对待，需要对市场进行二次验证入场。</p>',31)])])}const q=e(h,[["render",p]]);export{b as __pageData,q as default};
